<?php
declare(strict_types=1);
chdir(__DIR__ . '/..');
require_once __DIR__ . '/../php/session_security.php';
AppSessionStart();
require_once __DIR__ . '/../php/db_connection.php';
require_once __DIR__ . '/../php/admin_auth_helper.php';
require_once __DIR__ . '/../php/activity_logger.php';
require_once __DIR__ . '/../php/reviews_feedback_helper.php';
AdminRequireLogin();
ensureReviewModerationColumns($pdo);
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');

function re(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function rjson(int $code, bool $success, string $message): never { http_response_code($code); header('Content-Type: application/json'); echo json_encode(['success'=>$success,'message'=>$message]); exit; }
function rurl(int $page): string { $query=$_GET; unset($query['export']); $query['page']=$page; return 'adreviewsfeedback.php?'.http_build_query($query); }
function initials(string $name): string { $parts=preg_split('/\s+/',trim($name))?:[]; return strtoupper(substr((string)($parts[0]??'V'),0,1).(count($parts)>1?substr((string)end($parts),0,1):'')); }
function touristProfileImage(?string $value): string {
    $value=trim((string)$value); if($value==='')return '';
    if(preg_match('#^https?://#i',$value)||str_starts_with($value,'//'))return $value;
    $clean=ltrim(str_replace('\\','/',$value),'/'); $candidates=[$clean,'uploads/profile_pictures/'.basename($clean),'uploads/profile_picture/'.basename($clean),'img/'.basename($clean)];
    foreach(array_unique($candidates)as$candidate){if(is_file(dirname(__DIR__).'/'.$candidate))return $candidate;} return '';
}

if (empty($_SESSION['admin_reviews_csrf'])) $_SESSION['admin_reviews_csrf']=bin2hex(random_bytes(32));
$csrf=(string)$_SESSION['admin_reviews_csrf']; $adminId=(int)($_SESSION['admin_id']??0); $adminName=(string)($_SESSION['admin_name']??$_SESSION['username']??'Administrator');
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!hash_equals($csrf,(string)($_POST['csrf_token']??''))) rjson(403,false,'Your security token expired. Refresh and try again.');
    $action=strtolower(trim((string)($_POST['action']??'update'))); $allowed=['published','hidden','flagged'];
    if ($action==='bulk') {
        $status=strtolower(trim((string)($_POST['status']??''))); $rawIds=$_POST['review_ids']??null;
        if (!is_array($rawIds)||!$rawIds||count($rawIds)>100) rjson(422,false,'Select reviews and a valid bulk action.');
        $ids=[]; foreach($rawIds as $rawId){if(!is_string($rawId)||!preg_match('/^[1-9]\d*$/D',$rawId))rjson(422,false,'Select reviews and a valid bulk action.');$id=filter_var($rawId,FILTER_VALIDATE_INT);if($id===false)rjson(422,false,'Select reviews and a valid bulk action.');$ids[]=$id;} $ids=array_values(array_unique($ids));
        if (!in_array($status,$allowed,true)||!$ids) rjson(422,false,'Select reviews and a valid bulk action.');
        $marks=implode(',',array_fill(0,count($ids),'?')); $stmt=$pdo->prepare("UPDATE feedback SET moderation_status=?,moderated_by=?,moderated_at=NOW() WHERE feedback_id IN ({$marks})"); $stmt->execute(array_merge([$status,$adminId],$ids));
        logActivity($pdo,'Admin',$adminId,$adminName,'Reviews Moderated',ucfirst($status).' '.$stmt->rowCount().' selected review(s).','Reviews',null); rjson(200,true,$stmt->rowCount().' review(s) updated.');
    }
    $id=(int)($_POST['review_id']??0); $status=strtolower(trim((string)($_POST['moderation_status']??''))); $note=trim((string)($_POST['admin_note']??'')); $reply=trim((string)($_POST['admin_reply']??''));
    if ($id<1||!in_array($status,$allowed,true)) rjson(422,false,'Select a valid review status.');
    if (mb_strlen($note)>3000||mb_strlen($reply)>2000) rjson(422,false,'The note or reply is too long.');
    $stmt=$pdo->prepare('UPDATE feedback SET moderation_status=?,admin_note=?,admin_reply=?,moderated_by=?,moderated_at=NOW() WHERE feedback_id=?'); $stmt->execute([$status,$note!==''?$note:null,$reply!==''?$reply:null,$adminId,$id]);
    if (!$stmt->rowCount()) { $check=$pdo->prepare('SELECT COUNT(*) FROM feedback WHERE feedback_id=?');$check->execute([$id]);if(!(int)$check->fetchColumn())rjson(404,false,'Review not found.'); }
    logActivity($pdo,'Admin',$adminId,$adminName,'Review Updated','Updated review #'.$id.' to '.$status.'.','Reviews',$id); rjson(200,true,'Review updated successfully.');
}

$typeSql=reviewTypeSql('f'); $search=trim((string)($_GET['search']??'')); $type=strtolower(trim((string)($_GET['type']??''))); $rating=(int)($_GET['rating']??0); $status=strtolower(trim((string)($_GET['status']??''))); $period=strtolower(trim((string)($_GET['period']??'all'))); $sort=strtolower(trim((string)($_GET['sort']??'newest'))); $page=max(1,(int)($_GET['page']??1)); $perPage=12;
$types=['package','tourguide','boat','service'];$statuses=['published','hidden','flagged'];$where=["({$typeSql}) IS NOT NULL"];$params=[];
if($search!==''){$where[]="(f.comment LIKE :search OR t.full_name LIKE :search OR t.email LIKE :search OR tp.package_title LIKE :search OR g.fullname LIKE :search OR b.name LIKE :search OR sp.service_name LIKE :search)";$params[':search']='%'.$search.'%';}
if(in_array($type,$types,true)){$where[]="({$typeSql})=:type";$params[':type']=$type;}else$type='';
if($rating>=1&&$rating<=5){$where[]='f.rating=:rating';$params[':rating']=$rating;}else$rating=0;
if(in_array($status,$statuses,true)){$where[]='f.moderation_status=:status';$params[':status']=$status;}else$status='';
$periodDays=['7d'=>7,'30d'=>30,'90d'=>90];if(isset($periodDays[$period]))$where[]='f.created_at >= DATE_SUB(NOW(), INTERVAL '.$periodDays[$period].' DAY)';else$period='all';
$orders=['newest'=>'f.created_at DESC','oldest'=>'f.created_at ASC','highest'=>'f.rating DESC,f.created_at DESC','lowest'=>'f.rating ASC,f.created_at DESC'];if(!isset($orders[$sort]))$sort='newest';
$from=" FROM feedback f LEFT JOIN tourist t ON t.tourist_id=f.tourist_id LEFT JOIN tour_packages tp ON tp.package_id=COALESCE(f.package_id,IF(({$typeSql})='package',NULLIF(f.service_id,0),NULL)) LEFT JOIN tour_guides g ON g.guide_id=COALESCE(f.tourguide_id,IF(({$typeSql})='tourguide',NULLIF(f.service_id,0),NULL)) LEFT JOIN boats b ON b.boat_id=COALESCE(f.boat_id,IF(({$typeSql})='boat',NULLIF(f.service_id,0),NULL)) LEFT JOIN service_prices sp ON sp.price_id=IF(({$typeSql})='service',NULLIF(f.service_id,0),NULL)";$whereSql=' WHERE '.implode(' AND ',$where);
$countStmt=$pdo->prepare('SELECT COUNT(*)'.$from.$whereSql);$countStmt->execute($params);$total=(int)$countStmt->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$select="SELECT f.*,({$typeSql}) review_type,t.full_name tourist_name,t.email tourist_email,t.phone_number tourist_phone,t.address tourist_address,t.profile_picture tourist_profile_picture,COALESCE(tp.package_title,g.fullname,b.name,sp.service_name,CONCAT('Service #',NULLIF(f.service_id,0)),'Unavailable listing') item_name";$stmt=$pdo->prepare($select.$from.$whereSql.' ORDER BY '.$orders[$sort]." LIMIT {$perPage} OFFSET {$offset}");$stmt->execute($params);$reviews=$stmt->fetchAll(PDO::FETCH_ASSOC);foreach($reviews as&$review)$review['tourist_profile_url']=touristProfileImage((string)($review['tourist_profile_picture']??''));unset($review);
$scopeWhere=" WHERE ({$typeSql}) IS NOT NULL";$summary=$pdo->query("SELECT COUNT(*) total,ROUND(COALESCE(AVG(f.rating),0),1) average_rating,SUM(f.moderation_status='published') published,SUM(f.moderation_status='flagged') flagged,SUM(f.admin_reply IS NOT NULL AND TRIM(f.admin_reply)<>'') replied,SUM(f.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) recent".$from.$scopeWhere)->fetch(PDO::FETCH_ASSOC)?:[];$ratingRows=$pdo->query("SELECT f.rating,COUNT(*) total FROM feedback f {$scopeWhere} GROUP BY f.rating")->fetchAll(PDO::FETCH_KEY_PAIR);$categoryRows=$pdo->query("SELECT ({$typeSql}) review_type,COUNT(*) total,ROUND(AVG(f.rating),1) average FROM feedback f {$scopeWhere} GROUP BY review_type ORDER BY FIELD(review_type,'package','tourguide','boat','service')")->fetchAll(PDO::FETCH_ASSOC);$categoryStats=[];foreach($categoryRows as$row)$categoryStats[(string)$row['review_type']]=$row;$allTotal=max(1,(int)($summary['total']??0));
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="reviews-feedback-'.date('Y-m-d').'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Review ID','Category','Item','Visitor','Email','Rating','Review','Status','Admin reply','Submitted']);foreach($reviews as$review)fputcsv($out,[$review['feedback_id'],reviewTypeLabel((string)$review['review_type']),$review['item_name'],$review['tourist_name'],$review['tourist_email'],$review['rating'],$review['comment'],$review['moderation_status'],$review['admin_reply'],$review['created_at']]);fclose($out);exit;}
$hasFilters=$search!==''||$type!==''||$rating>0||$status!==''||$period!=='all';
?>
