#fbfdfc!important;font-size:10px;outline:0}.rf-form select{height:41px;padding:0 10px}.rf-form textarea{min-height:93px;padding:10px;line-height:1.55;resize:vertical}.rf-form textarea.reply{min-height:112px}.rf-form select:focus,.rf-form textarea:focus{border-color:#64a68f!important;background:#fff!important;box-shadow:0 0 0 3px #26785f16}.rf-help{display:flex;gap:7px;margin:-3px 0 13px;padding:9px;border:1px solid #dce9e4;border-radius:9px;color:#6e837b;background:#f5f9f7;font-size:8.5px;line-height:1.5}.rf-help:before{content:"i";display:grid;width:16px;height:16px;flex:0 0 16px;place-items:center;border-radius:50%;color:#fff;background:#4b8e77;font-size:9px;font-weight:850}.rf-save{width:100%;height:42px;font-size:10.5px}.rf-toast{position:fixed;right:20px;bottom:20px;z-index:15000;padding:11px 14px;border-radius:10px;color:#fff;background:#236f58;font-size:10px;font-weight:750}.rf-toast.error{background:#ad3545}.rf-toast[hidden]{display:none}
