</style></head><body><div class="admin-container"><?php include __DIR__.'/admin_sidebar.php';?><main class="main-content"><header class="admin-header admin-page-header rf-head"><div class="admin-header-left admin-page-title rf-title"><span class="admin-page-title-icon"><svg viewBox="0 0 24 24"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg></span><div class="admin-page-title-copy"><h2>Reviews &amp; Feedback</h2><p class="admin-header-subtitle">Monitor ratings and visitor experiences across tourism services</p></div></div><div class="admin-header-right"><span class="rf-head-badge"><?=number_format((int)($summary['recent']??0))?> received in 30 days</span></div></header>
<div class="rf-content"><section class="rf-overview" aria-label="Review overview"><?php $kpis=[['Average rating',number_format((float)($summary['average_rating']??0),1).' / 5',number_format((int)($summary['total']??0)).' total reviews','<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>'],['Published',number_format((int)($summary['published']??0)),round(((int)($summary['published']??0)/$allTotal)*100).'% visible to visitors','<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>'],['Admin replies',number_format((int)($summary['replied']??0)),round(((int)($summary['replied']??0)/$allTotal)*100).'% response coverage','<path d="M4 5h16v12H8l-4 3V5Z"/><path d="M8 9h8M8 13h5"/>'],['Needs attention',number_format((int)($summary['flagged']??0)),'Flagged for administrator review','<path d="M5 21V4m0 1h11l-2 4 2 4H5"/>']];foreach($kpis as$i=>$k):?><article class="rf-kpi <?=$i===0?'primary':''?>"><div class="rf-kpi-top"><div><small><?=re($k[0])?></small><strong><?=re($k[1])?></strong></div><span class="rf-kpi-icon"><svg viewBox="0 0 24 24"><?=$k[3]?></svg></span></div><p><?=re($k[2])?></p></article><?php endforeach;?></section>
<section class="rf-insights"><article class="rf-card"><div class="rf-card-head"><h3>Rating distribution</h3><span>All review categories</span></div><?php for($star=5;$star>=1;$star--):$count=(int)($ratingRows[$star]??0);?><div class="rf-rating-row"><b><?=$star?> star</b><span class="rf-bar"><i style="width:<?=round($count/$allTotal*100)?>%"></i></span><span><?=number_format($count)?></span></div><?php endfor;?></article><article class="rf-card"><div class="rf-card-head"><h3>Reviews by category</h3><span>Average rating and volume</span></div><div class="rf-categories"><?php foreach($types as$kind):$cs=$categoryStats[$kind]??['total'=>0,'average'=>0];?><div class="rf-category"><span><?=re(reviewTypeLabel($kind))?></span><strong><?=number_format((int)$cs['total'])?></strong><small>★ <?=number_format((float)$cs['average'],1)?> average</small></div><?php endforeach;?></div></article></section>
<section class="rf-panel"><form class="rf-toolbar" method="get"><div class="rf-field rf-search"><label>Search reviews</label><input name="search" value="<?=re($search)?>" placeholder="Visitor, listing, email, or comment"></div><?php $filters=[['type','Category',[''=>'All categories','package'=>'Tour packages','tourguide'=>'Tour guides','boat'=>'Boats','service'=>'Services'],$type],['rating','Rating',['0'=>'All ratings','5'=>'5 stars','4'=>'4 stars','3'=>'3 stars','2'=>'2 stars','1'=>'1 star'],(string)$rating],['status','Visibility',[''=>'All statuses','published'=>'Published','hidden'=>'Hidden','flagged'=>'Flagged'],$status],['period','Period',['all'=>'All time','7d'=>'Last 7 days','30d'=>'Last 30 days','90d'=>'Last 90 days'],$period],['sort','Sort by',['newest'=>'Newest first','oldest'=>'Oldest first','highest'=>'Highest rated','lowest'=>'Lowest rated'],$sort]];foreach($filters as[$name,$label,$options,$selected]):?><div class="rf-field"><label><?=re($label)?></label><select name="<?=re($name)?>"><?php foreach($options as$value=>$text):?><option value="<?=re($value)?>" <?=$selected===(string)$value?'selected':''?>><?=re($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="rf-actions"><button class="rf-btn primary" type="submit">Apply</button><a class="rf-btn" href="adreviewsfeedback.php">Reset</a><a class="rf-btn" href="<?=re(rurl($page).'&export=csv')?>">CSV</a></div></form>
<form class="rf-bulk" id="bulkBar"><input type="hidden" name="csrf_token" value="<?=re($csrf)?>"><input type="hidden" name="action" value="bulk"><span><b id="selectedCount">0</b> reviews selected</span><div class="rf-bulk-actions"><button class="rf-btn" type="submit" name="status" value="published">Publish</button><button class="rf-btn" type="submit" name="status" value="hidden">Hide</button><button class="rf-btn" type="submit" name="status" value="flagged">Flag</button></div></form>
<?php if(!$reviews):?><div class="rf-empty"><svg viewBox="0 0 24 24"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg><h3><?=$hasFilters?'No matching reviews':'No tourism reviews yet'?></h3><p><?=$hasFilters?'Adjust or clear the current filters.':'Tour package, guide, boat, and service reviews will appear here.'?></p></div><?php else:?><div class="rf-table-wrap"><table class="rf-table"><thead><tr><th><input class="rf-check" id="selectAll" type="checkbox" aria-label="Select all reviews"></th><th>Visitor</th><th>Category &amp; listing</th><th>Rating</th><th>Review</th><th>Visibility</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($reviews as$review):$stars=str_repeat('★',(int)$review['rating']).str_repeat('☆',5-(int)$review['rating']);$reviewerName=(string)($review['tourist_name']?:'Visitor #'.$review['tourist_id']);?><tr><td><input class="rf-check rowCheck" type="checkbox" name="review_ids[]" value="<?=(int)$review['feedback_id']?>" form="bulkBar" aria-label="Select review <?=(int)$review['feedback_id']?>"></td><td><div class="rf-person"><span class="rf-avatar"><?php if($review['tourist_profile_url']!==''):?><img src="<?=re($review['tourist_profile_url'])?>" alt="" onerror="this.remove();this.parentElement.textContent='<?=re(initials($reviewerName))?>'"><?php else:?><?=re(initials($reviewerName))?><?php endif;?></span><div><strong><?=re($reviewerName)?></strong><span><?=re($review['tourist_email']?:'No email available')?></span></div></div></td><td><div class="rf-target"><span class="rf-type"><?=re(reviewTypeLabel((string)$review['review_type']))?></span><strong title="<?=re($review['item_name'])?>"><?=re($review['item_name'])?></strong></div></td><td><span class="rf-stars"><?=re($stars)?><b><?=number_format((float)$review['rating'],1)?></b></span></td><td class="rf-comment"><p><?=re($review['comment'])?></p><?php if(!empty($review['admin_reply'])):?><span class="rf-replied">✓ Admin replied</span><?php endif;?></td><td><span class="rf-pill <?=re($review['moderation_status'])?>"><?=re($review['moderation_status'])?></span></td><td class="rf-date"><?=date('M j, Y',strtotime($review['created_at']))?><small><?=date('g:i A',strtotime($review['created_at']))?></small></td><td><button class="rf-btn rf-view" type="button" data-review="<?=re(json_encode($review,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12s3-5 8-5 8 5 8 5-3 5-8 5-8-5-8-5Z"/><circle cx="12" cy="12" r="2"/></svg>Manage</button></td></tr><?php endforeach;?></tbody></table></div><footer class="rf-footer"><span>Showing <?=$offset+1?>–<?=min($offset+$perPage,$total)?> of <?=number_format($total)?> reviews</span><nav class="rf-pages"><a class="rf-page <?=$page<=1?'disabled':''?>" href="<?=re(rurl(max(1,$page-1)))?>">‹</a><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><a class="rf-page <?=$p===$page?'active':''?>" href="<?=re(rurl($p))?>"><?=$p?></a><?php endfor;?><a class="rf-page <?=$page>=$pages?'disabled':''?>" href="<?=re(rurl(min($pages,$page+1)))?>">›</a></nav></footer><?php endif;?></section></div></main></div>
<div class="rf-drawer" id="reviewDrawer" hidden><section class="rf-drawer-panel" role="dialog" aria-modal="true" aria-labelledby="drawerTitle"><header class="rf-drawer-head"><div class="rf-drawer-title"><span class="rf-drawer-icon"><svg viewBox="0 0 24 24"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg></span><div><h2 id="drawerTitle">Manage review</h2><p id="drawerSubtitle"></p></div></div><button class="rf-close" type="button" aria-label="Close">×</button></header><div class="rf-drawer-body"><div class="rf-detail"><section class="rf-review-hero"><span class="rf-hero-avatar" id="drawerAvatar"></span><div><small>Submitted by</small><strong id="drawerName">Visitor</strong><span id="drawerHeroMeta"></span></div></section><article class="rf-detail-card"><h3>Experience reviewed</h3><div class="rf-context" id="drawerContext"></div></article><article class="rf-detail-card"><h3>Visitor feedback</h3><div class="rf-feedback-rating"><div class="rf-full-stars" id="drawerStars"></div><span class="rf-score-badge" id="drawerScore"></span></div><div class="rf-full-comment" id="drawerComment"></div></article><article class="rf-detail-card"><h3>Visitor contact details</h3><div class="rf-context" id="drawerVisitor"></div></article></div><aside class="rf-moderate"><form class="rf-form" id="reviewForm"><input type="hidden" name="csrf_token" value="<?=re($csrf)?>"><input type="hidden" name="action" value="update"><input type="hidden" name="review_id" id="reviewId"><h3>Moderation controls</h3><p class="rf-moderate-intro">Control where this feedback appears and keep a clear record of the response.</p><label><span>Visibility status</span><select name="moderation_status" id="reviewStatus"><option value="published">Published — visible</option><option value="hidden">Hidden — not visible</option><option value="flagged">Flagged — needs attention</option></select></label><label><span>Public admin reply</span><textarea class="reply" name="admin_reply" id="reviewReply" maxlength="2000" placeholder="Write a courteous response to the visitor..."></textarea></label><label><span>Internal note</span><textarea name="admin_note" id="reviewNote" maxlength="3000" placeholder="Add moderation context for administrators only..."></textarea></label><p class="rf-help">Public replies may be shown with the review on visitor-facing pages. Internal notes remain visible only to administrators.</p><button class="rf-btn primary rf-save" type="submit">Save review changes</button></form></aside></div></section></div><div class="rf-toast" id="rfToast" hidden></div>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-review]').forEach(function(button){button.addEventListener('click',function(){window.queueMicrotask(function(){try{var review=JSON.parse(button.dataset.review),name=review.tourist_name||('Visitor #'+review.tourist_id),parts=name.trim().split(/\s+/),letters=((parts[0]||'V').charAt(0)+(parts.length>1?parts[parts.length-1].charAt(0):'')).toUpperCase(),avatar=document.getElementById('drawerAvatar');avatar.replaceChildren();if(review.tourist_profile_url){var image=document.createElement('img');image.src=review.tourist_profile_url;image.alt='';image.addEventListener('error',function(){avatar.textContent=letters});avatar.appendChild(image)}else avatar.textContent=letters;document.getElementById('drawerName').textContent=name;document.getElementById('drawerHeroMeta').textContent=(review.tourist_email||'No email available')+' · '+(review.item_name||'Unavailable listing');document.getElementById('drawerScore').textContent=Number(review.rating||0).toFixed(1)+' out of 5';var visitor=document.getElementById('drawerVisitor'),address=document.createElement('div'),small=document.createElement('small'),strong=document.createElement('strong');address.className='rf-data';small.textContent='Address';strong.textContent=review.tourist_address||'Not available';address.append(small,strong);visitor.appendChild(address)}catch(error){}})})})});</script>
<script>(()=>{const drawer=document.getElementById('reviewDrawer'),form=document.getElementById('reviewForm'),toast=document.getElementById('rfToast'),bulk=document.getElementById('bulkBar'),checks=[...document.querySelectorAll('.rowCheck')],all=document.getElementById('selectAll');const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const labels={package:'Tour Package',tourguide:'Tour Guide',boat:'Boat',service:'Service'};const date=v=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}):'Not recorded';const box=(n,v)=>`<div class="rf-data"><small>${esc(n)}</small><strong>${esc(v||'Not available')}</strong></div>`;function notify(message,error=false){toast.textContent=message;toast.classList.toggle('error',error);toast.hidden=false;setTimeout(()=>toast.hidden=true,3200)}function openReview(r){reviewId.value=r.feedback_id;reviewStatus.value=r.moderation_status||'published';reviewReply.value=r.admin_reply||'';reviewNote.value=r.admin_note||'';drawerSubtitle.textContent=`Review #${r.feedback_id} · ${labels[r.review_type]||'Service'}`;drawerContext.innerHTML=box('Category',labels[r.review_type]||'Service')+box('Listing',r.item_name)+box('Submitted',date(r.created_at))+box('Status',String(r.moderation_status||'published').replace(/^./,c=>c.toUpperCase()));drawerVisitor.innerHTML=box('Visitor',r.tourist_name||`Visitor #${r.tourist_id}`)+box('Email',r.tourist_email)+box('Phone',r.tourist_phone);drawerStars.textContent='★'.repeat(Number(r.rating)||0)+'☆'.repeat(5-(Number(r.rating)||0));drawerComment.textContent=r.comment||'No written feedback.';drawer.hidden=false;document.body.style.overflow='hidden'}function close(){drawer.hidden=true;document.body.style.overflow=''}document.querySelectorAll('[data-review]').forEach(button=>button.onclick=()=>{try{openReview(JSON.parse(button.dataset.review))}catch(e){notify('Unable to open this review.',true)}});document.querySelector('.rf-close').onclick=close;drawer.onclick=e=>{if(e.target===drawer)close()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden)close()});async function post(data){const response=await fetch('adreviewsfeedback.php',{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}});const payload=await response.json();if(!response.ok||!payload.success)throw Error(payload.message||'Update failed.');return payload}form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Saving...';try{const result=await post(new FormData(form));notify(result.message);setTimeout(()=>location.reload(),650)}catch(error){notify(error.message,true);button.disabled=false;button.textContent='Save review changes'}};function syncBulk(){const selected=checks.filter(c=>c.checked).length;document.getElementById('selectedCount').textContent=selected;bulk.classList.toggle('active',selected>0);if(all){all.checked=selected===checks.length&&selected>0;all.indeterminate=selected>0&&selected<checks.length}}checks.forEach(c=>c.onchange=syncBulk);if(all)all.onchange=()=>{checks.forEach(c=>c.checked=all.checked);syncBulk()};bulk.onsubmit=async e=>{e.preventDefault();const submitter=e.submitter;if(!submitter||!checks.some(c=>c.checked))return;const data=new FormData(bulk);data.set('status',submitter.value);submitter.disabled=true;try{const result=await post(data);notify(result.message);setTimeout(()=>location.reload(),650)}catch(error){notify(error.message,true);submitter.disabled=false}}})();</script></body></html>
